struct Resource { int value; };

// Preferred creation: Atomically allocates control block and object
auto p1 = std::make_shared<Resource>(42);

// Establish shared ownership
std::shared_ptr<Resource> p2 = p1;

p1->value = 10; // Access via operator->
(*p2).value = 20; // Access via operator*

size_t count = p1.use_count(); // count == 2

// p1 releases ownership (count becomes 1)
p1.reset(); 

// Resource is destroyed when p2 goes out of scope (count hits 0)


// --- Custom Deleter Example ---

// Use raw pointer initializer for custom deleters
std::shared_ptr<int> p3(
    new int[10], 
    [](int* raw_ptr) { 
        delete[] raw_ptr; 
    } 
);

// Manages a C-style file handle
FILE* f = fopen("log.txt", "r");
auto close_file = [](FILE* fp) { if (fp) fclose(fp); };
std::shared_ptr<FILE> file_ptr(f, close_file);
// Resource automatically closed on destruction.
